WITH exploded AS (SELECT id, customer_id, coupon_codes, INLINE(items) FROM carts) SELECT product_id, CASE WHEN price >= 245 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, CASE WHEN qty >= 4 THEN 'HIGH' ELSE 'LOW' END AS qty_tier, ROUND(SUM(product_id) / NULLIF(COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END), 0), 2) AS product_id_per_welcome5, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN promo = 'BUNDLE' THEN 1 END), 0), 2) AS price_per_bundle, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN promo = 'BUNDLE' THEN 1 END), 0), 2) DESC) AS price_per_bundle_percent_rank FROM exploded GROUP BY 1, 2, 3
